import React, { useState, useEffect } from 'react';

const API = 'http://localhost:5000/api';

function PurchaseGame({ user }) {
  const [games, setGames] = useState([]);
  const [selectedGame, setSelectedGame] = useState('');
  const [copies, setCopies] = useState([]);
  const [selectedCopy, setSelectedCopy] = useState('');
  const [msg, setMsg] = useState({ type: '', text: '' });
  const [purchases, setPurchases] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetch(`${API}/games`).then(r => r.json()).then(d => setGames(Array.isArray(d) ? d : d.games || [])).catch(() => {});
    fetchPurchases();
  }, []);

  useEffect(() => {
    if (!selectedGame) return setCopies([]);
    fetch(`${API}/games/${selectedGame}/physical-copies`)
      .then(r => r.json())
      .then(d => setCopies(Array.isArray(d) ? d : []))
      .catch(() => setCopies([]));
  }, [selectedGame]);

  const fetchPurchases = async () => {
    try {
      const res = await fetch(`${API}/purchases/user/${user.userID || user.id}`);
      const data = await res.json();
      setPurchases(Array.isArray(data) ? data : []);
    } catch { setPurchases([]); }
  };

  const handlePurchase = async (e) => {
    e.preventDefault();
    setMsg({ type: '', text: '' });
    if (!selectedCopy) return setMsg({ type: 'error', text: 'Select a copy.' });
    setLoading(true);
    try {
      const res = await fetch(`${API}/purchases/purchase`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: user.userID || user.id, copyId: selectedCopy })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || data.error || 'Failed');
      setMsg({ type: 'success', text: 'Purchase successful!' });
      setSelectedGame(''); setSelectedCopy('');
      fetchPurchases();
    } catch (err) {
      setMsg({ type: 'error', text: err.message });
    }
    setLoading(false);
  };

  return (
    <div>
      <h2 style={heading}>Purchase a Game</h2>

      {msg.text && <p style={{ color: msg.type === 'success' ? '#00ff88' : '#fc8181', marginBottom: '1rem' }}>{msg.text}</p>}

      <div style={card}>
        <form onSubmit={handlePurchase}>
          <div style={formGroup}>
            <label style={label}>Select Game</label>
            <select style={select} value={selectedGame} onChange={e => { setSelectedGame(e.target.value); setSelectedCopy(''); }} required>
              <option value="">-- Choose a game --</option>
              {games.map((g, i) => <option key={g.gameID || i} value={g.gameID || g.id}>{g.title || g.name}</option>)}
            </select>
          </div>
          <div style={formGroup}>
            <label style={label}>Physical Copy</label>
            <select style={select} value={selectedCopy} onChange={e => setSelectedCopy(e.target.value)} required>
              <option value="">-- Choose a copy --</option>
              {copies.map((c, i) => (
                <option key={c.copyID || i} value={c.copyID || c.id}>
                  Copy #{c.copyID || c.id} — {c.isAvailable || c.availability === 1 ? 'Available' : 'Unavailable'}
                </option>
              ))}
            </select>
          </div>
          <button type="submit" style={primaryBtn} disabled={loading}>{loading ? 'Processing...' : 'Buy Now'}</button>
        </form>
      </div>

      <h3 style={{ ...heading, marginTop: '2rem' }}>My Purchases</h3>
      <table style={table}>
        <thead>
          <tr>{['Game', 'Purchase Date', 'Amount'].map(h => <th key={h} style={th}>{h}</th>)}</tr>
        </thead>
        <tbody>
          {purchases.length === 0
            ? <tr><td colSpan={3} style={{ ...td, color: '#aaa', textAlign: 'center' }}>No purchases yet</td></tr>
            : purchases.map((p, i) => (
              <tr key={p.purchaseID || i}>
                <td style={td}>{p.gameTitle || p.title || `Game #${p.gameID}`}</td>
                <td style={td}>{p.purchaseDate ? new Date(p.purchaseDate).toLocaleDateString() : '—'}</td>
                <td style={{ ...td, color: '#00ff88' }}>{p.totalAmount ? `$${Number(p.totalAmount).toFixed(2)}` : '—'}</td>
              </tr>
            ))}
        </tbody>
      </table>
    </div>
  );
}

const heading = { color: '#fff', marginBottom: '1rem' };
const card = { background: '#1a1a2e', padding: '1.5rem', borderRadius: 12, marginBottom: '1.5rem', maxWidth: 500 };
const formGroup = { marginBottom: '1rem' };
const label = { display: 'block', color: '#aaa', fontSize: '0.85rem', marginBottom: '0.4rem' };
const select = { width: '100%', padding: '0.6rem 1rem', background: '#0f0f1a', border: '1px solid #333', borderRadius: 8, color: '#fff', fontSize: '0.9rem' };
const primaryBtn = { width: '100%', padding: '0.65rem', background: '#ff6b35', color: '#fff', border: 'none', borderRadius: 8, fontWeight: 700, cursor: 'pointer', fontSize: '0.95rem' };
const table = { width: '100%', borderCollapse: 'collapse' };
const th = { textAlign: 'left', padding: '0.75rem 1rem', color: '#aaa', fontSize: '0.8rem', borderBottom: '1px solid #333', textTransform: 'uppercase' };
const td = { padding: '0.75rem 1rem', color: '#ccc', borderBottom: '1px solid #222', fontSize: '0.9rem' };

export default PurchaseGame;
